<script setup lang="ts">import {ref} from 'vue';import {parseCards} from '../engine/cardText';const emit=defineEmits<{apply:[hole:number[],board:(number|null)[]]}>();const hole=ref(''),board=ref(''),error=ref('');function apply(){try{const h=parseCards(hole.value),b=parseCards(board.value);if(h.length!==2||![0,3,4,5].includes(b.length))throw Error('底牌须 2 张，公共牌须 0/3/4/5 张');if(new Set([...h,...b]).size!==h.length+b.length)throw Error('底牌与公共牌重复');emit('apply',h,[...b,...Array(5-b.length).fill(null)]);error.value=''}catch(e){error.value=(e as Error).message}}</script><template><details class="panel"><summary>快速输入牌张文本</summary><div class="fields"><label>底牌<input v-model="hole" placeholder="As Kh"></label><label>公共牌<input v-model="board" placeholder="Qs Jh 2d"></label></div><p class="muted">s/h/d/c 分别为黑桃、红桃、方块、梅花；支持 10 或 T。</p><button class="secondary full" @click="apply">应用牌张</button><p class="error" v-if="error">{{error}}</p></details></template>
